grid=[[0]*22 for _ in range(22)]
objs=[('A',1,17,2,1),('B',4,12,2,7),('C',2,0,8,1),('D',8,17,2,3),('E',10,12,2,6),('F',14,5,8,6),('G',15,17,2,4),('H',15,0,8,9)]
for name,r,c,bg,fg in objs:
    for i in range(5):
        for j in range(5):
            grid[r+i][c+j]=bg if i in (0,4) or j in (0,4) else fg
print('\n'.join(' '.join(map(str,row)) for row in grid))

